#!/bin/zsh
# fill_one.sh <mid frame>: repaint one pinball gap frame in the world's look (refs: layout, style, him, her)
W=${0:A:h}; G=$W/..; T=$G/gpt/typist-contender-1; m=$1; f=$(printf 'f%05d' $m)
[[ -f $W/keyframes/gap/$f.png ]] && exit 0
P="Repaint image 1 in the painting style, light and palette of image 2 (flat gouache, soft painted texture, simple shapes; not realistic, not 3D). Keep image 1's composition, every object and every piece of text exactly as written, including partial or mid-flip words. If the main man appears (long grey coat, black hat, guitar case, or later his colourful sweater and striped trousers), draw his face and figure exactly as on image 3; if the woman with the rose-red collar appears, draw her exactly as on image 4. Every other person is a faceless clerk with a blank head under a black hat. Ministry interiors get brass pneumatic message tubes and ducts at the edges; the sky never does (the sky is the escape from the ministry: no tubes, pipes or machinery there). Where image 1 shows blue sky or strong colour, keep that colour; otherwise use the grey-teal palette of image 2 with rose as the only warm accent."
$G/gpt/gptimg -o $W/keyframes/gap/$f.png -r $W/src/gap/$f.jpg -r $T/env_hall_ducts_tubes.png -r $W/characters/him_turnaround.png -r $W/characters/her_turnaround.png "$P" > $W/src/gap/$f.log 2>&1
